import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 998244353L;
    static final long INV2 = (MOD + 1) / 2;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner();
        PrintWriter out = new PrintWriter(System.out);
        long n = sc.nextInt();
        long m = sc.nextInt();
        long l = sc.nextInt();
        long r = sc.nextInt();
        long k = r - l;
        long even = k / 2 + 1;
        long odd = (k + 1) / 2;
        long cells = n * m;
        if (cells % 2 == 1) {
            out.print(powMod(k + 1, cells, MOD));
        } else {
            long a = powMod(even + odd, cells, MOD);
            long b = powMod(even - odd, cells, MOD);
            long ans = ((a + b) % MOD) * INV2 % MOD;
            out.println(ans);
        }
        out.flush();
    }

    static long powMod(long base, long exp, long mod) {
        if (exp < 0) throw new ArithmeticException("Negative exponent");
        base %= mod;
        if (base < 0) base += mod;
        long res = 1 % mod;
        while (exp > 0) {
            if ((exp & 1L) == 1L) res = res * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return res;
    }

    static class Scanner {
        BufferedReader br;
        StringTokenizer st;

        Scanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
